export const baseTypeDefs = "\"\"\"\nMarketly GraphQL base. Shared by the three schemas (store, seller, admin).\n\nRules (see docs/api/graphql/README.md):\n- GraphQL is for READING complex screen data. All writes stay on REST (idempotency, approvals, audit).\n- Each module contributes a fragment in docs/api/graphql/modules/<module>.graphql:\n  its own types, `extend type Query` fields, and fields it adds to other modules' types.\n- The module that owns the data resolves the field (@source). Removing a module removes its fields.\n- @areas decides which schema(s) a type or field appears in. No @areas = all three.\n\"\"\"\nschema {\n  query: Query\n}\n\ntype Query {\n  \"Schema health check. Real queries are contributed by modules.\"\n  ping: String!\n}\n\n# ------------------------------------------------------------------ directives\n\n\"Which API area schemas include this type or field. Omitted = STORE, SELLER and ADMIN.\"\ndirective @areas(in: [Area!]!) on OBJECT | FIELD_DEFINITION | ENUM | INPUT_OBJECT | UNION\n\n\"\"\"\nWho may read this field. `permission` is a staff or seller permission key from the REST spec.\nSeller-area fields are always limited to the caller's own seller account.\nOn fields visible in both SELLER and ADMIN areas, `permission` is checked for staff callers; seller callers are always\nlimited to their own seller account. A field that needs different rules per area is declared once per area in\nseparate `extend type` blocks (e.g. Seller.balance, Case.order).\n\"\"\"\ndirective @auth(requires: Auth!, permission: String) on FIELD_DEFINITION | OBJECT\n\n\"\"\"\nWhich module resolves this field and with which in-process function (publicApi in the module's REST spec).\nDocuments ownership; the resolver batches calls per request (DataLoader).\n\"\"\"\ndirective @source(module: String!, fn: String!) on FIELD_DEFINITION\n\n\"\"\"\nRelative cost for the query cost limit. Lists default to 10, other fields to 1. A query's cost is the sum over\nevery selected field (each alias and each fragment spread counts); above 1,500 it is refused (QUERY_TOO_COMPLEX).\n\"\"\"\ndirective @cost(weight: Int!) on FIELD_DEFINITION\n\n\"\"\"\nA sensitive field: the GraphQL side of a REST spec type field with `permission` and `mask` (same permission, same mask).\nIn the SELLER and ADMIN areas the server masks it centrally unless the caller holds the permission:\n`email` → a***@example.com, `phone` → ***12, `name` → A., `hide` → null. Resolvers never decide.\n\"\"\"\ndirective @sensitive(permission: String!, mask: String!) on FIELD_DEFINITION\n\n\"Planned for a later launch phase (plan ch. 20). The field resolves to null until then.\"\ndirective @phase(n: Int!) on FIELD_DEFINITION | OBJECT\n\nenum Area {\n  STORE\n  SELLER\n  ADMIN\n}\n\nenum Auth {\n  \"No session needed\"\n  ANYONE\n  \"Customer or guest session\"\n  SHOPPER\n  CUSTOMER\n  SELLER\n  STAFF\n}\n\n# ------------------------------------------------------------------ scalars\n\n\"UUIDv7 string\"\nscalar UUID\n\"ISO 8601 timestamp in UTC\"\nscalar DateTime\n\"YYYY-MM-DD\"\nscalar Date\nscalar URL\nscalar Email\n\"Free-form JSON (only where the REST spec uses json)\"\nscalar JSON\n\n# ------------------------------------------------------------------ shared types (mirror common.json)\n\n\"Integer minor units (cents) and ISO 4217 currency. 18900 USD = $189.00\"\ntype Money {\n  amount: Int!\n  currency: String!\n  \"Formatted for display in the market locale, e.g. $189.00\"\n  formatted: String!\n}\n\ntype Address {\n  name: String!\n  line1: String!\n  line2: String\n  city: String!\n  region: String!\n  postalCode: String!\n  country: String!\n  phone: String\n}\n\ntype MediaRef {\n  id: UUID!\n  url: URL!\n  alt: String\n  width: Int\n  height: Int\n  \"File size in bytes (media's sizeBytes), shown next to attachments and evidence files, e.g. 212 KB\"\n  bytes: Int\n}\n\nenum ActorKind {\n  CUSTOMER\n  GUEST\n  SELLER\n  STAFF\n  SYSTEM\n}\n\ntype Actor {\n  kind: ActorKind!\n  id: String\n  name: String\n}\n\ntype TimelineEvent {\n  at: DateTime!\n  label: String!\n  detail: String\n  actor: Actor\n}\n\nenum DeadlineState {\n  ON_TIME\n  DUE_SOON\n  OVERDUE\n}\n\ntype Deadline {\n  dueAt: DateTime!\n  state: DeadlineState!\n}\n\ntype ApprovalInfo {\n  required: Boolean!\n  reason: String\n  approvalRequestId: UUID\n  approvers: [String!]!\n}\n\n\"\"\"\nPaging input, same as REST: `cursor` for the Android app's infinite scroll, `page` for the website's numbered pages.\n\"\"\"\ninput PageInput {\n  cursor: String\n  page: Int\n  \"1–100, default 24\"\n  limit: Int\n}\n\n\"\"\"\nEvery list returns `<Type>Page { items, nextCursor, page, totalPages, total }`, the same shape as REST.\n\"\"\"\ninterface Paged {\n  nextCursor: String\n  page: Int\n  totalPages: Int\n  total: Int\n}\n";

